"""Conservative SQL policy. SQL is untrusted even when generated by our model."""
import sqlglot
from sqlglot import exp


class UnsafeSQL(ValueError):
    pass


SAFE_FUNCTIONS = frozenset({
    'COUNT', 'SUM', 'AVG', 'MIN', 'MAX', 'ABS', 'ROUND', 'COALESCE',
    'EXISTS', 'LOWER', 'UPPER', 'LENGTH', 'CAST', 'EXTRACT', 'DATE', 'DATE_TRUNC',
    'TIMESTAMP_TRUNC', 'SUBSTRING', 'TRIM', 'NULLIF', 'GREATEST', 'LEAST',
})


def validate_sql(sql, dialect, allowed_tables, max_rows=200):
    if not isinstance(sql, str) or not sql.strip() or len(sql) > 20000:
        raise UnsafeSQL('Provide one SQL query of at most 20,000 characters.')
    if dialect not in {'sqlite', 'postgres', 'mysql'}:
        raise UnsafeSQL('Unsupported database dialect.')
    try:
        statements = sqlglot.parse(sql, read=dialect)
    except sqlglot.errors.SqlglotError as exc:
        raise UnsafeSQL('SQL could not be parsed.') from exc
    if len(statements) != 1 or not isinstance(statements[0], exp.Select):
        raise UnsafeSQL('Only one SELECT statement is allowed.')
    tree = statements[0]
    # Fail closed on advanced constructs; subqueries and joins remain supported.
    blocked = (exp.DML, exp.DDL, exp.Command, exp.Into, exp.Lock,
               exp.With, exp.CTE, exp.Union, exp.Intersect, exp.Except, exp.Dot,
               exp.Placeholder, exp.Parameter, exp.SessionParameter, exp.TableSample)
    for node in tree.walk():
        if isinstance(node, blocked) or node.comments:
            raise UnsafeSQL('This SQL construct is not permitted.')
        if isinstance(node, exp.Select):
            permitted = {'expressions', 'from_', 'joins', 'where', 'group',
                         'having', 'order', 'limit', 'offset', 'distinct'}
            if any(value and key not in permitted for key, value in node.args.items()):
                raise UnsafeSQL('Unsupported SELECT clause.')
        if isinstance(node, exp.Table):
            if (not isinstance(node.this, exp.Identifier) or node.catalog or
                    (node.db, node.name) not in allowed_tables):
                raise UnsafeSQL('Table is outside the approved schema.')
        if isinstance(node, exp.DataType) and node.this == exp.DataType.Type.USERDEFINED:
            raise UnsafeSQL('Custom data types are not approved.')
        if isinstance(node, exp.Func) and not isinstance(node, (exp.Connector, exp.Case, exp.If)):
            name = node.name.upper() if isinstance(node, exp.Anonymous) else node.sql_name()
            if name not in SAFE_FUNCTIONS:
                raise UnsafeSQL('Function is not approved.')
    tree = tree.limit(max_rows + 1) if not tree.args.get('limit') else tree
    limit = tree.args['limit'].expression
    if not isinstance(limit, exp.Literal) or not limit.is_int or int(limit.this) < 0:
        raise UnsafeSQL('LIMIT must be a nonnegative integer.')
    tree.set('limit', exp.Limit(expression=exp.Literal.number(min(int(limit.this), max_rows + 1))))
    return tree.sql(dialect=dialect)
